package com.gathin.tvhome;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.graphics.Color;
import android.graphics.drawable.*;
import android.media.tv.TvInputManager;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;
/** Explicit user actions only. No app sweeper, background polling or arbitrary shell entry point. */
public final class RecentAppsActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private LinearLayout row;private TextView status,all,done;private boolean busy;private int generation;private final List<String> displayed=new ArrayList<>();
    @Override protected void onCreate(Bundle state){super.onCreate(state);Window w=getWindow();w.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams attrs=w.getAttributes();attrs.dimAmount=.8f;w.setAttributes(attrs);w.getDecorView().setSystemUiVisibility(5894);
        FrameLayout root=new FrameLayout(this);LinearLayout panel=GlassDialog.panel(this);GradientDrawable glass=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xF03E4857,0xF61C2531,0xF6101721});glass.setCornerRadius(dp(24));glass.setStroke(dp(1),0x99CADBF2);panel.setBackground(glass);panel.setElevation(dp(18));panel.setPadding(dp(26),dp(22),dp(26),dp(22));panel.addView(GlassDialog.text(this,"Geöffnete Apps",26));status=GlassDialog.text(this,"Apps werden geladen …",12);status.setTextColor(0xFFBDCADB);panel.addView(status);
        HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);scroll.setClipToPadding(false);row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(5),dp(16),dp(5),dp(12));scroll.addView(row,new HorizontalScrollView.LayoutParams(-2,-1));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(208));sp.topMargin=dp(8);panel.addView(scroll,sp);
        LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER);all=button("Alle schließen");all.setOnClickListener(v->closeApps(new ArrayList<>(displayed)));actions.addView(all,new LinearLayout.LayoutParams(dp(190),dp(42)));done=button("Zurück");done.setOnClickListener(v->finish());LinearLayout.LayoutParams donep=new LinearLayout.LayoutParams(dp(130),dp(42));donep.setMarginStart(dp(12));actions.addView(done,donep);panel.addView(actions);panel.addView(GlassDialog.text(this,"OK: App öffnen · Unten ×: schließen · Systemdienste bleiben geöffnet",11));
        FrameLayout.LayoutParams pp=new FrameLayout.LayoutParams(-1,-2);root.addView(panel,pp);setContentView(root);w.setLayout(Math.min(dp(850),getResources().getDisplayMetrics().widthPixels-dp(48)),WindowManager.LayoutParams.WRAP_CONTENT);w.setGravity(Gravity.CENTER);RecentAppsAppearance.apply(this);NavigationSounds.attach(this,w);refresh();}
    private int dp(float x){return GlassDialog.dp(this,x);}
    private TextView button(String text){TextView t=DesignPopup.button(this,text);t.setTextSize(15);t.setBackground(SettingsSheet.rowBackground(this));t.setTextColor(SettingsSheet.ink(Color.WHITE,0xFF17202B));return t;}
    private Set<String> protectedPackages(){Set<String> set=new HashSet<>();set.add(getPackageName());for(ResolveInfo r:getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME),0))set.add(r.activityInfo.packageName);String bound=android.provider.Settings.Secure.getString(getContentResolver(),"enabled_accessibility_services");if(bound!=null)for(String s:bound.split(":")){ComponentName c=ComponentName.unflattenFromString(s);if(c!=null)set.add(c.getPackageName());}TvInputManager tv=getSystemService(TvInputManager.class);if(tv!=null)try{for(android.media.tv.TvInputInfo i:tv.getTvInputList())set.add(i.getServiceInfo().packageName);}catch(RuntimeException ignored){}return set;}
    private boolean eligible(String pkg){if(!RecentAppsPolicy.safe(pkg)||protectedPackages().contains(pkg))return false;try{ApplicationInfo a=getPackageManager().getApplicationInfo(pkg,0);return a.enabled&&a.uid%100000>=10000&&(getPackageManager().getLeanbackLaunchIntentForPackage(pkg)!=null||getPackageManager().getLaunchIntentForPackage(pkg)!=null);}catch(PackageManager.NameNotFoundException e){return false;}}
    private void refresh(){int request=++generation;busy=true;all.setEnabled(false);worker.execute(()->{try{List<String> packages=RecentAppsPolicy.packages(LocalCecReader.readRecentApps(),android.os.Process.myUid()/100000);List<String> visible=new ArrayList<>();for(String pkg:packages)if(eligible(pkg))visible.add(pkg);main.post(()->{if(isFinishing()||request!=generation)return;displayed.clear();displayed.addAll(visible);render();});}catch(Exception e){main.post(()->{if(isFinishing())return;busy=false;all.setEnabled(false);status.setText("Lokale ADB-Verbindung benötigt. In Ton & HDMI-CEC die lokale Verbindung freigeben; Debugging muss aktiv sein.");});}});}
    private void render(){busy=false;row.removeAllViews();status.setText(displayed.isEmpty()?"Keine geöffneten Apps zum Schließen":displayed.size()+(displayed.size()==1?" App · Links/Rechts wählen":" Apps · Links/Rechts wählen"));all.setEnabled(!displayed.isEmpty());for(String pkg:displayed){try{PackageManager pm=getPackageManager();ApplicationInfo info=pm.getApplicationInfo(pkg,0);String name=AppAppearance.label(this,pkg,pm.getApplicationLabel(info).toString());LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setGravity(Gravity.CENTER);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(dp(190),-1);cp.setMarginEnd(dp(16));row.addView(card,cp);ImageView icon=new ImageView(this);Drawable image=AppAppearance.icon(this,pkg);if(image==null){Intent launch=pm.getLeanbackLaunchIntentForPackage(pkg);try{ActivityInfo ai=launch==null||launch.getComponent()==null?null:pm.getActivityInfo(launch.getComponent(),0);image=ai==null?null:ai.loadBanner(pm);}catch(PackageManager.NameNotFoundException ignored){}if(image==null)image=pm.getApplicationIcon(info);}icon.setImageDrawable(image);icon.setScaleType(ImageView.ScaleType.FIT_CENTER);icon.setPadding(dp(7),dp(7),dp(7),dp(7));icon.setBackground(SettingsSheet.rowBackground(this));icon.setFocusable(true);icon.setFocusableInTouchMode(true);icon.setId(View.generateViewId());icon.setContentDescription(name+" öffnen");card.addView(icon,new LinearLayout.LayoutParams(-1,dp(116)));icon.setOnClickListener(v->{if(busy)return;Intent target=pm.getLeanbackLaunchIntentForPackage(pkg);if(target==null)target=pm.getLaunchIntentForPackage(pkg);if(target!=null){AppLock.launch(this,target.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));finish();}});icon.setOnFocusChangeListener((v,on)->{v.animate().scaleX(on?1.05f:1).scaleY(on?1.05f:1).setDuration(160).start();});TextView label=GlassDialog.text(this,name,12);label.setGravity(Gravity.CENTER);label.setSingleLine(true);label.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(label,new LinearLayout.LayoutParams(-1,dp(26)));TextView close=button("×");close.setTextSize(25);close.setId(View.generateViewId());close.setContentDescription(name+" schließen");card.addView(close,new LinearLayout.LayoutParams(dp(64),dp(34)));close.setOnClickListener(v->closeApps(Collections.singletonList(pkg)));icon.setNextFocusDownId(close.getId());close.setNextFocusUpId(icon.getId());if(row.getChildCount()==1)icon.requestFocus();}catch(PackageManager.NameNotFoundException ignored){}}if(displayed.isEmpty())done.requestFocus();}
    private void closeApps(List<String> packages){if(busy||packages.isEmpty())return;busy=true;all.setEnabled(false);status.setText("Apps werden geschlossen …");worker.execute(()->{String error=null;try{for(String pkg:packages){if(!eligible(pkg))continue;String result=LocalCecReader.stopRecentApp(pkg);if(result.contains("Exception")||result.contains("Error"))throw new IllegalStateException();}List<String> remaining=RecentAppsPolicy.packages(LocalCecReader.readRecentApps(),android.os.Process.myUid()/100000);for(String pkg:packages)if(remaining.contains(pkg))throw new IllegalStateException();}catch(Exception e){error="Schließen nicht bestätigt. Lokale ADB-Verbindung prüfen.";}String message=error;main.post(()->{if(isFinishing())return;if(message==null)refresh();else{busy=false;all.setEnabled(true);status.setText(message);}});});}
    @Override protected void onDestroy(){generation++;main.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}
}
